#include <unistd.h>
#include <sys/syscall.h>
#include <stdio.h>
#include <errno.h>

// Demonstrates the difference between invoking a system call via the glibc
// wrapper (getpid()) and invoking it directly (syscall(SYS_getpid)).
int main() {
    long pid_via_wrapper;
    long pid_via_syscall;

    printf("--- System Call Invocation Demonstration ---\n");

    // 1. Invocation using the standard glibc wrapper function (Recommended)
    // The wrapper handles setup and error checking transparently.
    pid_via_wrapper = getpid();
    printf("PID via glibc wrapper getpid(): %ld\n", pid_via_wrapper);

    // 2. Direct invocation using syscall(2)
    // Requires the specific system call number (SYS_getpid) defined in <sys/syscall.h>.
    // Parameters are passed variadically.
    pid_via_syscall = syscall(SYS_getpid);

    if (pid_via_syscall == -1) {
        // Error handling for syscall(2) relies on errno set by the wrapper logic.
        perror("Error invoking SYS_getpid directly");
        return 1;
    }

    printf("PID via direct syscall(2): %ld\n", pid_via_syscall);

    // Example of handling failure directly using syscall(2) for SYS_getppid (which should succeed)
    long ppid = syscall(SYS_getppid);
    if (ppid == -1) {
        fprintf(stderr, "Failed to get PPID. errno: %d\n", errno);
    }

    return 0;
}
